create extension if not exists pgcrypto;
create table public.games(id uuid primary key default gen_random_uuid(),game_date date not null,start_time time not null,duration_minutes int not null check(duration_minutes between 10 and 180),age_group text not null,location text not null,field_name text not null,public_notes text not null default '',is_open boolean not null default true,sort_order bigint generated always as identity,created_at timestamptz not null default now());
create table public.referee_signups(id uuid primary key default gen_random_uuid(),game_id uuid not null unique references public.games(id) on delete cascade,child_first text not null,child_last text not null,child_age int not null check(child_age between 12 and 16),parent_first text not null,parent_last text not null,parent_email text not null,parent_phone text not null,notes text not null default '',created_at timestamptz not null default now());
alter table public.games enable row level security; alter table public.referee_signups enable row level security; revoke all on public.games,public.referee_signups from anon,authenticated;
create or replace function public.is_refs_admin() returns boolean language sql stable as $$select auth.role()='authenticated' and lower(coalesce(auth.jwt()->>'email',''))='scott@cvsoccer.club'$$;
create or replace function public.get_open_games() returns table(id uuid,game_date date,start_time time,duration_minutes int,age_group text,location text,field_name text,public_notes text) language sql stable security definer set search_path=public as $$select g.id,g.game_date,g.start_time,g.duration_minutes,g.age_group,g.location,g.field_name,g.public_notes from games g left join referee_signups s on s.game_id=g.id where g.is_open and s.id is null and (g.game_date+g.start_time)>=now() order by g.game_date,g.start_time,g.sort_order$$;
create or replace function public.claim_referee_game(p_game_id uuid,p_child_first text,p_child_last text,p_child_age int,p_parent_first text,p_parent_last text,p_parent_email text,p_parent_phone text,p_notes text default '') returns jsonb language plpgsql security definer set search_path=public as $$declare target games%rowtype; ts timestamp; te timestamp; begin if p_child_age not between 12 and 16 then raise exception 'Referees must be between 12 and 16 years old'; end if; select * into target from games where id=p_game_id for update; if target.id is null or not target.is_open then raise exception 'This game is no longer available'; end if; if exists(select 1 from referee_signups where game_id=p_game_id) then raise exception 'This game was just claimed by another referee'; end if; ts:=target.game_date+target.start_time; te:=ts+make_interval(mins=>target.duration_minutes); if exists(select 1 from referee_signups s join games g on g.id=s.game_id where lower(trim(s.child_first))=lower(trim(p_child_first)) and lower(trim(s.child_last))=lower(trim(p_child_last)) and lower(trim(s.parent_email))=lower(trim(p_parent_email)) and (g.game_date+g.start_time)<te and (g.game_date+g.start_time+make_interval(mins=>g.duration_minutes))>ts) then raise exception 'This child is already signed up for a game that overlaps this time'; end if; insert into referee_signups(game_id,child_first,child_last,child_age,parent_first,parent_last,parent_email,parent_phone,notes) values(p_game_id,trim(p_child_first),trim(p_child_last),p_child_age,trim(p_parent_first),trim(p_parent_last),lower(trim(p_parent_email)),trim(p_parent_phone),trim(coalesce(p_notes,''))); return jsonb_build_object('ok',true); exception when unique_violation then raise exception 'This game was just claimed by another referee'; end$$;
create or replace function public.get_admin_games() returns table(id uuid,game_date date,start_time time,duration_minutes int,age_group text,location text,field_name text,public_notes text,is_open boolean,sort_order bigint,signup_id uuid,child_first text,child_last text,child_age int,parent_first text,parent_last text,parent_email text,parent_phone text,notes text,signup_created_at timestamptz) language plpgsql stable security definer set search_path=public as $$begin if not is_refs_admin() then raise exception 'Administrator sign-in required'; end if; return query select g.id,g.game_date,g.start_time,g.duration_minutes,g.age_group,g.location,g.field_name,g.public_notes,g.is_open,g.sort_order,s.id,s.child_first,s.child_last,s.child_age,s.parent_first,s.parent_last,s.parent_email,s.parent_phone,s.notes,s.created_at from games g left join referee_signups s on s.game_id=g.id order by g.game_date,g.start_time,g.sort_order; end$$;
create or replace function public.creator_add_games(p_game_date date,p_start_time time,p_duration_minutes int,p_age_group text,p_location text,p_game_count int,p_field_names text,p_public_notes text default '') returns jsonb language plpgsql security definer set search_path=public as $$declare names text[];i int;fname text;begin if not is_refs_admin() then raise exception 'Administrator sign-in required';end if;if p_game_count not between 1 and 20 then raise exception 'Number of games must be between 1 and 20';end if;names:=string_to_array(coalesce(p_field_names,''),',');for i in 1..p_game_count loop fname:=nullif(trim(coalesce(names[i],'')),'');if fname is null then fname:='Game '||i;end if;insert into games(game_date,start_time,duration_minutes,age_group,location,field_name,public_notes) values(p_game_date,p_start_time,p_duration_minutes,trim(p_age_group),trim(p_location),fname,trim(coalesce(p_public_notes,'')));end loop;return jsonb_build_object('ok',true,'created',p_game_count);end$$;
create or replace function public.creator_update_game(p_id uuid,p_game_date date,p_start_time time,p_duration_minutes int,p_age_group text,p_location text,p_field_name text,p_public_notes text,p_is_open boolean) returns jsonb language plpgsql security definer set search_path=public as $$begin if not is_refs_admin() then raise exception 'Administrator sign-in required';end if;update games set game_date=p_game_date,start_time=p_start_time,duration_minutes=p_duration_minutes,age_group=trim(p_age_group),location=trim(p_location),field_name=trim(p_field_name),public_notes=trim(coalesce(p_public_notes,'')),is_open=p_is_open where id=p_id;return jsonb_build_object('ok',true);end$$;
create or replace function public.creator_delete_game(p_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$begin if not is_refs_admin() then raise exception 'Administrator sign-in required';end if;delete from games where id=p_id;return jsonb_build_object('ok',true);end$$;
create or replace function public.creator_remove_signup(p_signup_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$begin if not is_refs_admin() then raise exception 'Administrator sign-in required';end if;delete from referee_signups where id=p_signup_id;return jsonb_build_object('ok',true);end$$;
revoke all on function public.get_open_games() from public;grant execute on function public.get_open_games() to anon,authenticated;grant execute on function public.claim_referee_game(uuid,text,text,int,text,text,text,text,text) to anon,authenticated;grant execute on function public.get_admin_games(),public.creator_add_games(date,time,int,text,text,int,text,text),public.creator_update_game(uuid,date,time,int,text,text,text,text,boolean),public.creator_delete_game(uuid),public.creator_remove_signup(uuid) to authenticated;
